<?php
 namespace ehr; require_once(__DIR__ . '/../../../../init.php'); require_once(__DIR__ . '/../autoload.php'); interface iResource { const RES_CAS_NONE = 0, RES_CAS_DPC = 1, RES_CAS_DB = 2; const RES_MO_PREFIX = 'Organization/', RES_MD_PREFIX = 'MedicationDispense/', RES_MP_PREFIX = 'MedicationPrescription/'; const RES_MEDICATION = 'Medication'; const DATE_FORMAT = "Y-m-d"; } abstract class Resource implements iResource { protected $query; protected $basicItem; protected $basicLink; protected $guidCache; protected $cas; protected $guid; protected $fieldName; protected $tableName; protected $name; protected $source; protected $record; protected $json; protected $json2; public function __construct(Link $link, string $aName, string $aTableName, $aSource) { $this->basicLink = $link; $this->link = $link; $this->guidCache = new LinkGUID(); $this->query = array(); $this->name = $aName; $this->tableName = $aTableName; $this->fieldName = "{$aTableName}Code"; $this->source = $aSource; $this->cas = self::RES_CAS_NONE; $this->createResourceItem(); } public function __destruct() { unset($this->guidCache); unset($this->basicItem); $this->name = ''; } public function getName(): string { return $this->name; } public function getSource(): int { return $this->source; } public function getLs(): ?LinkSetup { return $this->basicLink->getLs(); } public function setLs(): void { $this->basicLink->getLs()->saveLinkSetup(); } public function getFieldName(): string { return $this->fieldName; } public function getTableName(): string { return $this->tableName; } public function createResourceItem(): void { $this->basicItem = new ResourceItem($this); } public function getGuidCache(): ?LinkGUID { return $this->guidCache; } private function getCas(): int { return $this->cas; } public function setCas(int $cas): void { $this->cas = $cas; } public function getLink() { return $this->basicLink; } public function getGuid(int $key): string { $guidCache = $this->getGuidCache(); $guid = $guidCache->getGuid($key); if (empty($guid)) { try { switch ($this->getCas()) { case self::RES_CAS_DPC: $guid = $this->sendItem2DPC($key); break; case self::RES_CAS_DB: $guid = $this->getItemFromDB($key); break; } } catch (Throwable $exc) { } $this->setGuid($key, $guid); } return $guid; } public function setGuid(int $key, string $guid): void { $this->getGuidCache()->setGuid($key, $guid); } public function getBasicItem(): ?ResourceItem { return $this->basicItem; } public function getQuery(): array { return $this->query; } public function setQuery($query): void { empty($query) ? array_splice($this->query, 0) : $this->query = $query; } public function sendItem2DPC(int $key): ?string { $res = ''; $basicItem = $this->getBasicItem(); $basicItem->clearResourceItem(); $basicItem->setId($key); $query = $this->getQuery(); if (empty($query)) { return ''; } $this->record = -1; foreach ($query as $row => $record) { if ($record[$this->getFieldName()] == $key) { $this->record = $row; break; } } if ($this->record === -1) { return ''; } $basicItem->initData(current($query)); $basicItem->initJSONbase(); return $res; } public function send2DPC(string $sql): void { $this->setCas(self::RES_CAS_DPC); $basicLink = $this->getLink(); try { $this->setQuery(selectSql($basicLink->getConnetDb(), $sql)); $this->afterOpenBeforeSend(); foreach ($this->getQuery() as $row) { if (microtime() > $basicLink->getAccessTimeLimit()) { $basicLink->receiveAccessToken(); } $this->getGuid($row[$this->getFieldName()]); } } catch (Throwable $exc) { $basicLink->getLogger()->addLog($exc->getMessage(), 'exception', Logger::LMT_FATAL); } $this->setCas(self::RES_CAS_DB); } public static function deletePrefix(string $source, string $prefix): string { return str_replace($prefix, '', $source); } public static function dateFormat($date, string $format = self::DATE_FORMAT): string { $_date = new \DateTime($date); return $_date->format($format); } } 